class Bitset {
    int size;
    vector<int> bits;
    bool flipped;
    int ones;
public:
    Bitset(int size) : size(size), bits(size, 0), flipped(false), ones(0) {}
    void fix(int idx) {
        int val = bits[idx] ^ (flipped ? 1 : 0);
        if (val == 0) {
            bits[idx] = flipped ? 0 : 1;
            ones++;
        }
    }
    void unfix(int idx) {
        int val = bits[idx] ^ (flipped ? 1 : 0);
        if (val == 1) {
            bits[idx] = flipped ? 1 : 0;
            ones--;
        }
    }
    void flip() {
        flipped = !flipped;
        ones = size - ones;
    }
    bool all() { return ones == size; }
    bool one() { return ones > 0; }
    int count() { return ones; }
    string toString() {
        string s = "";
        s.reserve(size);
        for (int b : bits) {
            int val = b ^ (flipped ? 1 : 0);
            s += (val == 1 ? '1' : '0');
        }
        return s;
    }
};

class Bitset {
    int size;
    int[] bits;
    boolean flipped;
    int ones;
    public Bitset(int size) {
        this.size = size;
        this.bits = new int[size];
        this.flipped = false;
        this.ones = 0;
    }
    public void fix(int idx) {
        int val = bits[idx] ^ (flipped ? 1 : 0);
        if (val == 0) {
            bits[idx] = flipped ? 0 : 1;
            ones++;
        }
    }
    public void unfix(int idx) {
        int val = bits[idx] ^ (flipped ? 1 : 0);
        if (val == 1) {
            bits[idx] = flipped ? 1 : 0;
            ones--;
        }
    }
    public void flip() {
        flipped = !flipped;
        ones = size - ones;
    }
    public boolean all() { return ones == size; }
    public boolean one() { return ones > 0; }
    public int count() { return ones; }
    public String toString() {
        StringBuilder sb = new StringBuilder(size);
        for (int b : bits) {
            int val = b ^ (flipped ? 1 : 0);
            sb.append(val);
        }
        return sb.toString();
    }
}

var Bitset = function(size) {
    this.size = size;
    this.bits = new Uint8Array(size);
    this.flipped = false;
    this.ones = 0;
};
Bitset.prototype.fix = function(idx) {
    const val = this.bits[idx] ^ (this.flipped ? 1 : 0);
    if (val === 0) {
        this.bits[idx] = this.flipped ? 0 : 1;
        this.ones++;
    }
};
Bitset.prototype.unfix = function(idx) {
    const val = this.bits[idx] ^ (this.flipped ? 1 : 0);
    if (val === 1) {
        this.bits[idx] = this.flipped ? 1 : 0;
        this.ones--;
    }
};
Bitset.prototype.flip = function() {
    this.flipped = !this.flipped;
    this.ones = this.size - this.ones;
};
Bitset.prototype.all = function() { return this.ones === this.size; };
Bitset.prototype.one = function() { return this.ones > 0; };
Bitset.prototype.count = function() { return this.ones; };
Bitset.prototype.toString = function() {
    const chars = new Array(this.size);
    for (let i = 0; i < this.size; i++) {
        const val = this.bits[i] ^ (this.flipped ? 1 : 0);
        chars[i] = val === 1 ? '1' : '0';
    }
    return chars.join('');
};
